<template>
 <div class="house-preparation" data-house-preparation>
  <div class="prep-heading"><div><small>PRÉPARATION DU CAMP {{ duel.side===0?'BLEU':'ROUGE' }}</small><h3>{{ members.length===2?'Votre équipe, votre stratégie':'Prépare ton équipe' }}</h3></div><strong class="prep-clock" :class="{urgent:seconds<=20}" role="timer" :aria-label="`${seconds} secondes restantes`">{{ Math.floor(seconds/60) }}:{{ String(seconds%60).padStart(2,'0') }}</strong></div>
  <p class="prep-intro">{{ members.length===2?'Composez ensemble votre équipe. Toute modification retire vos confirmations.':'Choisis tes Pokémon et leur ordre, puis confirme pour rejoindre le combat.' }}</p>
  <nav class="prep-mobile-tabs" aria-label="Préparation"><button v-for="t in tabs" :key="t.key" :aria-pressed="pane===t.key" @click="pane=t.key">{{ t.label }}<b v-if="t.key==='chat'&&unread">{{ unread }}</b></button></nav>
  <div class="prep-columns">
   <section class="prep-roster" :class="{'mobile-active':pane==='roster'}" aria-label="Pokémon disponibles">
    <div class="prep-section-title"><h4>Pokémon disponibles</h4><span>{{ filtered.length }}</span></div>
    <div class="prep-owners"><button v-for="m in members" :key="m.ownerId" :aria-pressed="owner===m.ownerId" @click="owner=m.ownerId;limit=24">{{ m.ownerId===userId?'Mes Pokémon':m.username }}</button></div>
    <div class="prep-filters"><input v-model="query" type="search" placeholder="Chercher un Pokémon" aria-label="Chercher un Pokémon"><select v-model="source" aria-label="Emplacement"><option value="all">Équipe et PC</option><option value="team">Équipe</option><option value="pc">PC</option></select></div>
    <p v-if="!members.length" class="prep-help" role="status">Chargement de vos Pokémon…</p>
    <div class="prep-candidates"><article v-for="p in filtered.slice(0,limit)" :key="p.uuid" :class="{selected:chosen(p)}">
     <button :disabled="busy" :aria-pressed="chosen(p)" :data-house-candidate="p.uuid" @click="toggle(p)"><pokemon-portrait :src="sprite(p)"/><span><b>{{ p.name }}</b><small>N. {{ p.level }} <potential-star :value="p.potential"/></small><small>{{ p.heldItemName||'Sans objet' }}</small></span><i aria-hidden="true">{{ chosen(p)?'✓':'+' }}</i></button>
     <button class="prep-detail" :aria-label="`Fiche de ${p.name}`" @click="$emit('inspect',p)">Fiche</button>
    </article></div>
    <button v-if="filtered.length>limit" class="prep-more" @click="limit+=24">Afficher la suite</button><p v-if="members.length&&!filtered.length" class="prep-help">Aucun Pokémon avec ces filtres.</p>
   </section>
   <section class="prep-team" :class="{'mobile-active':pane==='team'}" aria-label="Équipe commune">
    <div class="prep-section-title"><h4>{{ members.length===2?'Équipe commune':'Ton équipe' }}</h4><strong>{{ composition.length }} / {{ preparation.target }}</strong></div>
    <div class="prep-contributions"><span v-for="m in members" :key="m.ownerId" :class="ownerClass(m.ownerId)"><i></i>{{ m.ownerId===userId?'Toi':m.username }} · {{ composition.filter(p=>p.ownerId===m.ownerId).length }} / 6</span></div>
    <ol class="prep-slots" :class="{'twelve-slots':preparation.target===12}"><li v-for="(p,i) in slots" :key="p?.uuid||`empty-${i}`" :class="p?ownerClass(p.ownerId):'empty'" :draggable="!!p&&!busy" @dragstart="startDrag($event,i)" @dragover.prevent @drop.prevent="drop(i)">
     <template v-if="p"><span class="prep-slot-number">{{ i+1 }}</span><button class="prep-slot-pokemon" :aria-label="`Fiche de ${p.name}`" @click="$emit('inspect',p)"><pokemon-portrait :src="sprite(p)"/><b>{{ p.name }}</b><small>{{ p.username }}</small><small>{{ p.heldItemName||'Sans objet' }}</small></button><div class="prep-slot-actions"><button :disabled="busy||i===0" :aria-label="`Avancer ${p.name}`" @click="move(i,i-1)">←</button><button :disabled="busy||i===composition.length-1" :aria-label="`Reculer ${p.name}`" @click="move(i,i+1)">→</button><button :disabled="busy" :aria-label="`Retirer ${p.name}`" @click="toggle(p)">×</button></div></template><span v-else>{{ i+1 }}<small>Place libre</small></span>
    </li></ol>
    <p v-if="localError" class="prep-error" role="alert">{{ localError }}</p>
    <p class="prep-help">{{ members.length===2?'Un à six Pokémon par allié.':'Ton premier Pokémon entre en jeu en premier.' }} {{ duel.config.uniqueItems?'Chaque objet tenu doit être unique dans le camp.':'' }}</p>
    <div v-if="preparation.proposals.length" class="prep-proposals"><small>DERNIÈRES PROPOSITIONS</small><button v-for="p in preparation.proposals" :key="p.ownerId" :disabled="busy" @click="propose(p.composition)"><span>{{ p.ownerId===userId?'Ta proposition':`Proposition de ${p.username}` }}</span><b>Reprendre ↗</b></button></div>
   </section>
   <section class="prep-chat" :class="{'mobile-active':pane==='chat'}" aria-label="Discussion du camp">
    <div class="prep-section-title"><h4>Discussion du duo</h4><span>Privée</span></div>
    <p v-if="!preparation.chat.length" class="prep-help">Un plan à partager ? Ton adversaire ne voit pas cette discussion.</p>
    <ol ref="messages" class="prep-messages" aria-live="polite" aria-relevant="additions"><li v-for="m in preparation.chat" :key="m.id" :class="{self:m.ownerId===userId}"><b>{{ m.username }}</b><p>{{ m.message }}</p></li></ol>
    <form @submit.prevent="send"><label class="sr-only" for="house-chat-input">Message à ton allié</label><input id="house-chat-input" v-model="message" maxlength="240" autocomplete="off" placeholder="On commence par qui ?"><button :disabled="busy||!message.trim()" aria-label="Envoyer le message">↑</button></form>
   </section>
  </div>
  <footer class="prep-footer"><div class="prep-validations"><span v-for="m in duel.sides[duel.side].members" :key="m.userId" :class="{confirmed:preparation.confirmed.includes(m.userId)}"><i>{{ preparation.confirmed.includes(m.userId)?'✓':'○' }}</i>{{ m.userId===userId?'Toi':m.username }}</span></div><div><button :disabled="busy" @click="$emit('cancel')">Annuler</button><button class="prep-confirm" data-house-confirm :disabled="busy||!complete||preparation.confirmed.includes(userId)||seconds<=0" @click="$emit('command','confirm',{sideRevision:preparation.revision})">{{ preparation.confirmed.includes(userId)?'Camp confirmé ✓':'Confirmer cette équipe' }}</button></div></footer>
 </div>
</template>
<script>
import PokemonPortrait from '../PokemonPortrait.vue';
import PotentialStar from '../PotentialStar.vue';
export default {
 components:{PokemonPortrait,PotentialStar},props:{duel:Object,rosters:Object,userId:Number,busy:Boolean,clock:Number},
 data(){return{owner:this.userId,query:'',source:'all',limit:24,pane:'team',message:'',localError:'',drag:null,readMessages:0};},
 computed:{preparation(){return this.duel.preparation;},members(){return this.rosters?.id===this.duel.id?this.rosters.members:[];},composition(){return this.preparation.composition.filter(Boolean);},slots(){return Array.from({length:this.preparation.target},(_,i)=>this.composition[i]||null);},seconds(){return Math.max(0,Math.ceil((this.duel.preparationDeadline-this.clock-(this.duel.serverOffset||0))/1000));},filtered(){return(this.members.find(m=>m.ownerId===this.owner)?.pokemons||[]).filter(p=>(this.source==='all'||p.source===this.source)&&p.name.toLocaleLowerCase().includes(this.query.toLocaleLowerCase()));},complete(){return this.composition.length===this.preparation.target&&this.members.every(m=>{const n=this.composition.filter(p=>p.ownerId===m.ownerId).length;return n>=1&&n<=6;});},unread(){return this.pane==='chat'?0:Math.max(0,this.preparation.chat.length-this.readMessages);},tabs(){return[{key:'team',label:'Équipe'},{key:'roster',label:'Pokémon'},...(this.duel.sides[this.duel.side].capacity===2?[{key:'chat',label:'Discussion'}]:[])];}},
 watch:{pane(pane){if(pane==='chat')this.readMessages=this.preparation.chat.length;},'preparation.chat.length'(){if(this.pane==='chat')this.readMessages=this.preparation.chat.length;this.$nextTick(()=>{const el=this.$refs.messages;if(el)el.scrollTop=el.scrollHeight;});},'preparation.revision'(){this.localError='';}},
 methods:{sprite(p){return`${this.$assetBase}img/pokemon/front/${p.pokemonId}.png`;},ownerClass(id){return this.duel.sides[this.duel.side].members[0]?.userId===id?'owner-a':'owner-b';},chosen(p){return this.composition.some(c=>c.uuid===p.uuid);},propose(composition){this.$emit('command','compose',{sideRevision:this.preparation.revision,composition:composition.filter(Boolean).map(({ownerId,uuid})=>({ownerId,uuid}))});},toggle(p){if(this.busy)return;const refs=[...this.composition],index=refs.findIndex(c=>c.uuid===p.uuid);if(index>=0)refs.splice(index,1);else{if(refs.length>=this.preparation.target){this.localError='Retire un Pokémon pour libérer une place.';return;}if(refs.filter(c=>c.ownerId===p.ownerId).length>=6){this.localError='Six Pokémon au maximum par allié.';return;}refs.push(p);}this.propose(refs);},move(from,to){if(to<0||to>=this.composition.length)return;const refs=[...this.composition];refs.splice(to,0,refs.splice(from,1)[0]);this.propose(refs);},startDrag(event,index){if(!this.composition[index]||this.busy){event.preventDefault();return;}this.drag={index,revision:this.preparation.revision};event.dataTransfer.setData('text/plain',this.composition[index].uuid);event.dataTransfer.effectAllowed='move';},drop(index){if(this.drag?.revision===this.preparation.revision)this.move(this.drag.index,Math.min(index,this.composition.length-1));this.drag=null;},send(){if(!this.message.trim()||this.busy)return;this.$emit('command','chat',{message:this.message.trim()},ok=>{if(ok)this.message='';});}}
};
</script>
